,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select "RESERVATION_ID",',
'    null LINK_CLASS,',
'    apex_page.get_url(p_items => ''P8_RESERVATION_ID'', p_values => "RESERVATION_ID") LINK,',
'    null ICON_CLASS,',
'    null LINK_ATTR,',
'    null ICON_COLOR_CLASS,',
'    case when coalesce(:P8_RESERVATION_ID,''0'') = "RESERVATION_ID"',
'      then ''is-active'' ',
'      else '' ''',
'    end LIST_CLASS,',
'    (substr("CHECK_IN", 1, 50)||( case when length("CHECK_IN") > 50 then ''...'' else '''' end )) LIST_TITLE,',
'    (substr("CHECK_OUT", 1, 50)||( case when length("CHECK_OUT") > 50 then ''...'' else '''' end )) LIST_TEXT,',
'    null LIST_BADGE',
'from "RESERVATION" x',
'where (:P8_SEARCH is null',
'        or upper(x."CHECK_IN") like ''%''||upper(:P8_SEARCH)||''%''',
'        or upper(x."CHECK_OUT") like ''%''||upper(:P8_SEARCH)||''%''',
'    )',
'order by "CHECK_IN"'))
,p_ajax_enabled=>'Y'
